import { toast } from "sonner";

// email: "someone@example.com"
// subject (optional): email subject line
export function handleEmailClick(email, subject) {
  // 1. Copy to clipboard (works on HTTPS in every modern browser)
  if (navigator.clipboard?.writeText) {
    navigator.clipboard.writeText(email).catch(() => {});
  }

  // 2. Show a toast so the user gets feedback
  toast.success("Email copied to clipboard", {
    description: email,
    duration: 4000,
  });

  // 3. Try to open the user's mail client (fails silently if none)
  const mailto = subject
    ? `mailto:${email}?subject=${encodeURIComponent(subject)}`
    : `mailto:${email}`;
  window.location.href = mailto;
}