import { useEffect, useState } from "react";

import { useLocation } from "react-router-dom";

import { Button } from "@/components/ui/button";

import { Input } from "@/components/ui/input";

import { Label } from "@/components/ui/label";

import { Textarea } from "@/components/ui/textarea";

import { Checkbox } from "@/components/ui/checkbox";

import { toast } from "sonner";

import { api } from "@/lib/api";

import { Heart, HandHeart, Loader2, Mail } from "lucide-react";

import { handleEmailClick } from "@/lib/emailClick";



const preset = [

  { id: "booster", amount: 5, label: "Booster", url: "https://buy.stripe.com/3cIfZicWd9pl3KK7D01Jm01" },

  { id: "supporter", amount: 10, label: "Supporter", url: "https://buy.stripe.com/6oUbJ26xPeJFa98g9w1Jm02" },

  { id: "promoter", amount: 25, label: "Promoter", url: "https://buy.stripe.com/5kQ4gAg8p8lh9544qO1Jm03" },

  { id: "advocate", amount: 50, label: "Advocate", url: "https://buy.stripe.com/5kQbJ26xPgRN6WW7D01Jm04" },

];



const CUSTOM_DONATION_URL = "https://buy.stripe.com/aFacN66xPdFBdlkbTg1Jm00";



const INTERESTS = ["Coaching / Sports", "Event Setup", "Buddy Volunteer", "Fundraising", "Photography", "Admin / Comms"];



export default function GetInvolvedPage() {

  const location = useLocation();



  useEffect(() => {

    if (location.hash) {

      const el = document.getElementById(location.hash.slice(1));

      if (el) setTimeout(() => el.scrollIntoView({ behavior: "smooth", block: "start" }), 60);

    }

  }, [location.hash]);



  return (

    <div data-testid="get-involved-page">

      {/* Hero */}

      <section className="bg-blue-radial border-b border-blue-100/60">

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16 sm:py-24">

          <div className="max-w-3xl anim-fade-up">

            <p className="text-sm font-semibold tracking-[0.18em] uppercase text-blue-600">Get involved</p>

            <h1 className="mt-3 font-display text-4xl sm:text-5xl lg:text-6xl font-bold tracking-tight text-slate-900 leading-[1.05]">

              Three simple ways to help and support us in our mission.

            </h1>

            <p className="mt-6 text-lg text-slate-600 leading-relaxed">

              Donate, sign up for a session, or volunteer your time. Everything makes a difference, no contribution goes unnoticed.

            </p>

          </div>

        </div>

      </section>



      {/* Donate */}

      <DonateSection />



      {/* Volunteer */}

      <VolunteerSection />



      {/* Contact / Info */}

      <ContactSection />

    </div>

  );

}



function DonateSection() {

  const [selected, setSelected] = useState("booster");

  const [custom, setCustom] = useState("");

  const [loading, setLoading] = useState(false);



  const useCustom = custom && Number(custom) > 0;



  const handleDonate = () => {

    setLoading(true);



    if (useCustom) {

      window.location.href = CUSTOM_DONATION_URL;

    } else {

      const selectedPreset = preset.find((p) => p.id === selected);

      if (selectedPreset?.url) {

        window.location.href = selectedPreset.url;

      } else {

        toast.error("Payment link not found. Please try again.");

        setLoading(false);

      }

    }

  };



  return (

    <section id="donate" className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20 sm:py-24">

      <div className="grid lg:grid-cols-[1fr,1.2fr] gap-10 items-start">

        <div>

          <div className="inline-flex items-center gap-2 bg-blue-50 border border-blue-100 rounded-full px-4 py-1.5">

            <Heart className="h-3.5 w-3.5 text-blue-600" />

            <span className="text-xs font-semibold tracking-[0.14em] uppercase text-blue-700">Donate</span>

          </div>

          <h2 className="mt-5 font-display text-3xl sm:text-4xl lg:text-5xl font-semibold tracking-tight text-slate-900 leading-tight">

            Fund a goal, a hike, a Saturday morning of belonging.

          </h2>

          <p className="mt-5 text-slate-600 leading-relaxed text-lg">

            100% of donations go directly toward equipment, venue fees, and training volunteers. Pick a preset amount or enter your own.

          </p>

        </div>



        <div className="rounded-3xl bg-white border border-slate-100 p-7 sm:p-9 card-soft">

          <h3 className="font-display text-2xl font-semibold text-slate-900">Make a one-time donation</h3>

          <p className="text-sm text-slate-500 mt-1">Secure checkout via Stripe.</p>



          <div className="mt-6 grid grid-cols-2 sm:grid-cols-4 gap-3">

            {preset.map((p) => {

              const active = !useCustom && selected === p.id;

              return (

                <button

                  key={p.id}

                  data-testid={`donate-preset-${p.id}`}

                  onClick={() => {

                    setSelected(p.id);

                    setCustom("");

                  }}

                  className={`rounded-2xl border px-3 py-4 text-left transition-all ${

                    active

                      ? "border-blue-600 bg-blue-600 text-white shadow-lg shadow-blue-500/25"

                      : "border-slate-200 bg-white hover:border-blue-300 text-slate-900"

                  }`}

                >

                  <div className={`text-[11px] uppercase tracking-widest ${active ? "text-blue-100" : "text-slate-500"}`}>

                    {p.label}

                  </div>

                  <div className="font-display text-2xl font-bold mt-1">${p.amount}</div>

                </button>

              );

            })}

          </div>



          <div className="mt-5">

            <Label htmlFor="custom-amount" className="text-xs uppercase tracking-widest text-slate-500">

              Or enter a custom amount

            </Label>

            <div className="relative mt-2">

              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500">$</span>

              <Input

                id="custom-amount"

                data-testid="donate-custom-amount"

                type="number"

                min="1"

                placeholder="Other amount"

                value={custom}

                onChange={(e) => setCustom(e.target.value)}

                className="pl-8 rounded-xl h-12 bg-slate-50 border-slate-200 focus-visible:ring-blue-500"

              />

            </div>

          </div>



          <Button

            data-testid="donate-submit-btn"

            onClick={handleDonate}

            disabled={loading}

            size="lg"

            className="mt-7 w-full rounded-full bg-blue-600 hover:bg-blue-700 text-white py-6 text-base font-semibold shadow-lg shadow-blue-500/25 hover:-translate-y-0.5 transition-all"

          >

            {loading ? (

              <><Loader2 className="h-5 w-5 mr-2 animate-spin" /> Redirecting to Stripe…</>

            ) : (

              <><Heart className="h-5 w-5 mr-2" /> Continue to secure checkout</>

            )}

          </Button>

          <p className="mt-4 text-xs text-slate-500 text-center">

            You'll be redirected to Stripe's secure payment page.

          </p>

        </div>

      </div>

    </section>

  );

}



function VolunteerSection() {

  const [form, setForm] = useState({

    name: "",

    email: "",

    phone: "",

    message: "",

  });



  const [interests, setInterests] = useState([]);

  const [loading, setLoading] = useState(false);



  const update = (key) => (event) => {

    setForm((currentForm) => ({

      ...currentForm,

      [key]: event.target.value,

    }));

  };



  const toggleInterest = (interest) => {

    setInterests((previousInterests) =>

      previousInterests.includes(interest)

        ? previousInterests.filter((item) => item !== interest)

        : [...previousInterests, interest]

    );

  };



  const submit = async (event) => {

    event.preventDefault();



    if (!form.name || !form.email) {

      toast.error("Please provide your name and email.");

      return;

    }



    setLoading(true);



    try {

      await api.post("/volunteers", {

        ...form,

        interests,

      });



      toast.success("Welcome to the team! We'll reach out with onboarding details.");



      setForm({

        name: "",

        email: "",

        phone: "",

        message: "",

      });



      setInterests([]);

    } catch (err) {

      toast.error(err?.response?.data?.detail || "Could not submit. Please try again.");

    } finally {

      setLoading(false);

    }

  };



  return (

    <section id="volunteer" className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20 sm:py-24">

      <div className="grid lg:grid-cols-[1fr,1.2fr] gap-10 items-start">

        {/* Left side */}

        <div>

          <div className="inline-flex items-center gap-2 bg-blue-50 border border-blue-100 rounded-full px-4 py-1.5">

            <HandHeart className="h-3.5 w-3.5 text-blue-600" />

            <span className="text-xs font-semibold tracking-[0.14em] uppercase text-blue-700">

              Volunteer

            </span>

          </div>



          <h2 className="mt-5 font-display text-3xl sm:text-4xl lg:text-5xl font-semibold tracking-tight text-slate-900 leading-tight">

            Two hours a week can change a life, including yours.

          </h2>



          <p className="mt-5 text-slate-600 leading-relaxed text-lg">

            We make sure every volunteer is kind and helpful towards children.

            No sports experience needed. Patience and a big smile go a long way.

          </p>



          <div className="mt-6 rounded-2xl bg-blue-50/60 border border-blue-100 p-5 text-sm text-slate-700">

            <p className="font-semibold text-slate-900">What happens next?</p>

            <p className="mt-1 text-slate-600">

              We'll email you within a few days with a short form, some volunteering rules, and a big welcome.

            </p>

          </div>

        </div>



        {/* Right side */}

        <div className="space-y-5">

          {/* Upcoming event card */}

          <div className="rounded-3xl border border-blue-200 bg-gradient-to-r from-blue-700 to-sky-400 p-6 sm:p-7 text-white shadow-xl shadow-blue-900/10">

            <div className="flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between">

              <div>

                <p className="text-xs font-semibold uppercase tracking-[0.16em] text-blue-100">

                  Upcoming event

                </p>

                <h3 className="mt-2 font-display text-2xl font-semibold">

                  Sign up for our next event

                </h3>

                <p className="mt-2 max-w-xl text-sm leading-relaxed text-blue-50">

                  Join us at our next Beyond Blades event. Spaces may be limited, so register early.

                </p>

              </div>



              <Button

                asChild

                size="lg"

                className="shrink-0 rounded-full bg-white px-6 font-semibold text-blue-700 hover:bg-blue-50"

              >

                <a

                  href="https://docs.google.com/forms/d/1nIzas5k_T9jeTjf5lOxIWuCM4MwfACmRU82teIwsB0E/viewform"

                  target="_blank"

                  rel="noopener noreferrer"

                  data-testid="event-signup-link"

                >

                  Register now

                </a>

              </Button>

            </div>

          </div>



          {/* Volunteer form */}

          <form

            onSubmit={submit}

            data-testid="volunteer-form"

            className="rounded-3xl bg-white border border-slate-100 p-7 sm:p-9 card-soft"

          >

            <h3 className="font-display text-2xl font-semibold text-slate-900">

              Become a volunteer

            </h3>



            <div className="mt-6 grid sm:grid-cols-2 gap-4">

              <div>

                <Label htmlFor="v-name">Full name</Label>

                <Input

                  id="v-name"

                  data-testid="volunteer-name"

                  value={form.name}

                  onChange={update("name")}

                  className="mt-2 rounded-xl h-12 bg-slate-50 border-slate-200"

                  required

                />

              </div>



              <div>

                <Label htmlFor="v-email">Email</Label>

                <Input

                  id="v-email"

                  data-testid="volunteer-email"

                  type="email"

                  value={form.email}

                  onChange={update("email")}

                  className="mt-2 rounded-xl h-12 bg-slate-50 border-slate-200"

                  required

                />

              </div>



              <div className="sm:col-span-2">

                <Label htmlFor="v-phone">Phone (optional)</Label>

                <Input

                  id="v-phone"

                  data-testid="volunteer-phone"

                  type="tel"

                  value={form.phone}

                  onChange={update("phone")}

                  className="mt-2 rounded-xl h-12 bg-slate-50 border-slate-200"

                />

              </div>

            </div>



            <div className="mt-5">

              <Label>Areas of interest</Label>

              <div className="mt-3 grid grid-cols-1 sm:grid-cols-2 gap-2">

                {INTERESTS.map((interest) => {

                  const checked = interests.includes(interest);

                  return (

                    <label

                      key={interest}

                      data-testid={`volunteer-interest-${interest

                        .toLowerCase()

                        .replace(/\s+/g, "-")

                        .replace(/\//g, "-")}`}

                      className={`flex items-center gap-3 rounded-xl border px-4 py-3 cursor-pointer transition-all ${

                        checked

                          ? "border-blue-600 bg-blue-50"

                          : "border-slate-200 hover:border-blue-300 bg-white"

                      }`}

                    >

                      <Checkbox

                        checked={checked}

                        onCheckedChange={() => toggleInterest(interest)}

                      />

                      <span className="text-sm font-medium text-slate-800">

                        {interest}

                      </span>

                    </label>

                  );

                })}

              </div>

            </div>



            <div className="mt-5">

              <Label htmlFor="v-message">

                Tell us about yourself (optional)

              </Label>

              <Textarea

                id="v-message"

                data-testid="volunteer-message"

                rows={4}

                value={form.message}

                onChange={update("message")}

                className="mt-2 rounded-xl bg-slate-50 border-slate-200"

                placeholder="Experience, availability, or anything you'd like us to know…"

              />

            </div>



            <Button

              data-testid="volunteer-submit-btn"

              type="submit"

              disabled={loading}

              size="lg"

              className="mt-7 w-full rounded-full bg-blue-600 hover:bg-blue-700 text-white py-6 text-base font-semibold"

            >

              {loading ? (

                <>

                  <Loader2 className="h-5 w-5 mr-2 animate-spin" />

                  Submitting…

                </>

              ) : (

                "Volunteer with us"

              )}

            </Button>

          </form>

        </div>

      </div>

    </section>

  );

}



function ContactSection() {

  const handleShare = () => {

    navigator.clipboard?.writeText(window.location.origin);

    toast.success("Link copied to clipboard!");

  };



  return (

    <section id="info" className="bg-gradient-to-b from-blue-50/50 to-white border-t border-blue-100/60">

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20 sm:py-24 grid md:grid-cols-3 gap-6">

        <InfoCard

          title="Questions?"

          desc="Reach out to us for any questions! We will do our best to respond within 1-2 business days!"

          cta={{

            label: "beyondbladesasdfoundation@gmail.com",

            onClick: () => handleEmailClick("beyondbladesasdfoundation@gmail.com"),

            testId: "contact-email-btn",

          }}

        />

        <InfoCard

          title="Partner with us"

          desc="Venues, schools, therapists, and community groups — we'd love to collaborate."

          cta={{

            label: "Start a conversation",

            onClick: () => handleEmailClick("beyondbladesasdfoundation@gmail.com", "Partnership"),

            testId: "partner-btn",

          }}

        />

        <InfoCard

          title="Spread the word"

          desc="Share Beyond Blades with one family who needs to find us."

          cta={{

            label: "Share this page",

            onClick: handleShare,

            testId: "share-btn",

          }}

        />

      </div>

    </section>

  );

}



function InfoCard({ title, desc, cta }) {

  return (

    <div className="rounded-3xl bg-white border border-slate-100 p-7 card-soft">

      <div className="h-11 w-11 rounded-2xl bg-blue-50 text-blue-700 flex items-center justify-center">

        <Mail className="h-5 w-5" />

      </div>

      <h3 className="mt-5 font-display text-xl font-semibold text-slate-900">{title}</h3>

      <p className="mt-2 text-sm text-slate-600 leading-relaxed">{desc}</p>

      <button

        data-testid={cta.testId}

        onClick={cta.onClick}

        className="mt-4 inline-flex text-sm font-semibold text-blue-700 hover:text-blue-800"

      >

        {cta.label} →

      </button>

    </div>

  );

}


