import { Link, NavLink, Outlet, useLocation } from "react-router-dom";
import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { Heart, Menu, X, ChevronDown } from "lucide-react";
import { FaInstagram, FaFacebookF, FaTiktok } from "react-icons/fa";
import { handleEmailClick } from "@/lib/emailClick";

const homeDropdown = [
  { to: "/", label: "Home", testId: "nav-home" },
  { to: "/about", label: "About", testId: "nav-about" },
  { to: "/our-team", label: "Our Team", testId: "nav-our-team" },
];

const getInvolvedDropdown = [
  {
    to: "/get-involved",
    label: "Get Involved",
    testId: "nav-get-involved",
  },
  {
    to: "/partners",
    label: "Partners",
    testId: "nav-partners",
  },
];

const normalNavItems = [
  { to: "/impact", label: "Impact", testId: "nav-impact" },
  { to: "/calendar", label: "Calendar", testId: "nav-calendar" },
];

function BrandMark() {
  return (
    <Link
      to="/"
      data-testid="brand-home-link"
      className="flex items-center gap-2.5 group"
    >
      <div className="relative h-14 w-14 rounded-2xl overflow-hidden shadow-lg shadow-blue-500/20 group-hover:scale-105 transition-transform">
        <img
          src={process.env.PUBLIC_URL + "/image_5.png"}
          alt="Beyond Blades logo"
          className="h-full w-full object-cover"
        />
      </div>

      <div className="leading-tight">
        <div className="font-display font-bold text-slate-900 text-base tracking-tight">
          Beyond Blades
        </div>

        <div className="text-[11px] uppercase tracking-[0.18em] text-blue-600 font-semibold">
          ASD Foundation
        </div>
      </div>
    </Link>
  );
}

function DesktopDropdown({ label, items, active }) {
  return (
    <div className="relative group">
      <button
        type="button"
        className={`flex items-center gap-1 px-4 py-2 rounded-full text-sm font-medium transition-all ${
          active
            ? "bg-blue-50 text-blue-700"
            : "text-slate-600 hover:text-slate-900 hover:bg-slate-50"
        }`}
      >
        {label}
        <ChevronDown className="h-4 w-4 transition-transform duration-200 group-hover:rotate-180" />
      </button>

      <div className="absolute top-full left-0 w-full h-2" />

      <div
        className="
          absolute left-0 top-[calc(100%+0.5rem)] z-50
          min-w-[190px] rounded-2xl border border-slate-200
          bg-white p-2 shadow-xl shadow-slate-900/10
          opacity-0 invisible translate-y-2
          group-hover:opacity-100 group-hover:visible group-hover:translate-y-0
          transition-all duration-200
        "
      >
        {items.map((item) => (
          <NavLink
            key={item.to}
            to={item.to}
            data-testid={item.testId}
            end={item.to === "/"}
            className={({ isActive }) =>
              `block rounded-xl px-4 py-3 text-sm font-medium transition-colors ${
                isActive
                  ? "bg-blue-50 text-blue-700"
                  : "text-slate-700 hover:bg-slate-50 hover:text-blue-700"
              }`
            }
          >
            {item.label}
          </NavLink>
        ))}
      </div>
    </div>
  );
}

export default function SiteLayout() {
  const [open, setOpen] = useState(false);
  const [mobileHomeOpen, setMobileHomeOpen] = useState(false);
  const [mobileGetInvolvedOpen, setMobileGetInvolvedOpen] = useState(false);

  const location = useLocation();

  useEffect(() => {
    setOpen(false);
    setMobileHomeOpen(false);
    setMobileGetInvolvedOpen(false);

    window.scrollTo({
      top: 0,
      behavior: "instant",
    });
  }, [location.pathname]);

  const homeIsActive =
    location.pathname === "/" ||
    location.pathname === "/about" ||
    location.pathname === "/our-team";

  const getInvolvedIsActive =
    location.pathname === "/get-involved" ||
    location.pathname === "/partners";

  return (
    <div className="min-h-screen flex flex-col bg-white text-slate-900">
      <header
        data-testid="site-header"
        className="sticky top-0 z-50 bg-white/80 backdrop-blur-xl border-b border-slate-200/60"
      >
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <BrandMark />

          <nav className="hidden md:flex items-center gap-1">
            <DesktopDropdown
              label="Home"
              items={homeDropdown}
              active={homeIsActive}
            />

            {normalNavItems.map((item) => (
              <NavLink
                key={item.to}
                to={item.to}
                data-testid={item.testId}
                className={({ isActive }) =>
                  `px-4 py-2 rounded-full text-sm font-medium transition-all ${
                    isActive
                      ? "bg-blue-50 text-blue-700"
                      : "text-slate-600 hover:text-slate-900 hover:bg-slate-50"
                  }`
                }
              >
                {item.label}
              </NavLink>
            ))}

            <DesktopDropdown
              label="Get Involved"
              items={getInvolvedDropdown}
              active={getInvolvedIsActive}
            />
          </nav>

          <div className="flex items-center gap-2">
            <Link to="/get-involved#donate" className="hidden sm:block">
              <Button
                data-testid="header-donate-btn"
                className="rounded-full bg-blue-600 hover:bg-blue-700 text-white px-5 shadow-lg shadow-blue-500/25 transition-all hover:-translate-y-0.5"
              >
                <Heart className="h-4 w-4 mr-1.5" />
                Donate
              </Button>
            </Link>

            <button
              data-testid="mobile-menu-toggle"
              onClick={() => setOpen((value) => !value)}
              className="md:hidden p-2 rounded-full hover:bg-slate-100"
              aria-label="Toggle menu"
            >
              {open ? (
                <X className="h-5 w-5" />
              ) : (
                <Menu className="h-5 w-5" />
              )}
            </button>
          </div>
        </div>

        {open && (
          <div
            data-testid="mobile-nav"
            className="md:hidden border-t border-slate-200 bg-white"
          >
            <div className="px-4 py-3 flex flex-col gap-1">
              <button
                type="button"
                onClick={() =>
                  setMobileHomeOpen((value) => !value)
                }
                className={`flex items-center justify-between px-4 py-3 rounded-xl text-sm font-medium ${
                  homeIsActive
                    ? "bg-blue-50 text-blue-700"
                    : "text-slate-700 hover:bg-slate-50"
                }`}
              >
                <span>Home</span>

                <ChevronDown
                  className={`h-4 w-4 transition-transform ${
                    mobileHomeOpen ? "rotate-180" : ""
                  }`}
                />
              </button>

              {mobileHomeOpen && (
                <div className="ml-4 border-l border-slate-200 pl-3 py-1 flex flex-col gap-1">
                  {homeDropdown.map((item) => (
                    <NavLink
                      key={item.to}
                      to={item.to}
                      end={item.to === "/"}
                      data-testid={`mobile-${item.testId}`}
                      className={({ isActive }) =>
                        `px-4 py-2.5 rounded-xl text-sm ${
                          isActive
                            ? "bg-blue-50 text-blue-700 font-medium"
                            : "text-slate-600 hover:bg-slate-50"
                        }`
                      }
                    >
                      {item.label}
                    </NavLink>
                  ))}
                </div>
              )}

              <NavLink
                to="/impact"
                data-testid="mobile-nav-impact"
                className={({ isActive }) =>
                  `px-4 py-3 rounded-xl text-sm font-medium ${
                    isActive
                      ? "bg-blue-50 text-blue-700"
                      : "text-slate-700 hover:bg-slate-50"
                  }`
                }
              >
                Impact
              </NavLink>

              <NavLink
                to="/calendar"
                data-testid="mobile-nav-calendar"
                className={({ isActive }) =>
                  `px-4 py-3 rounded-xl text-sm font-medium ${
                    isActive
                      ? "bg-blue-50 text-blue-700"
                      : "text-slate-700 hover:bg-slate-50"
                  }`
                }
              >
                Calendar
              </NavLink>

              <button
                type="button"
                onClick={() =>
                  setMobileGetInvolvedOpen((value) => !value)
                }
                className={`flex items-center justify-between px-4 py-3 rounded-xl text-sm font-medium ${
                  getInvolvedIsActive
                    ? "bg-blue-50 text-blue-700"
                    : "text-slate-700 hover:bg-slate-50"
                }`}
              >
                <span>Get Involved</span>

                <ChevronDown
                  className={`h-4 w-4 transition-transform ${
                    mobileGetInvolvedOpen ? "rotate-180" : ""
                  }`}
                />
              </button>

              {mobileGetInvolvedOpen && (
                <div className="ml-4 border-l border-slate-200 pl-3 py-1 flex flex-col gap-1">
                  {getInvolvedDropdown.map((item) => (
                    <NavLink
                      key={item.to}
                      to={item.to}
                      data-testid={`mobile-${item.testId}`}
                      className={({ isActive }) =>
                        `px-4 py-2.5 rounded-xl text-sm ${
                          isActive
                            ? "bg-blue-50 text-blue-700 font-medium"
                            : "text-slate-600 hover:bg-slate-50"
                        }`
                      }
                    >
                      {item.label}
                    </NavLink>
                  ))}
                </div>
              )}

              <Link to="/get-involved#donate" className="mt-2">
                <Button
                  data-testid="mobile-donate-btn"
                  className="w-full rounded-full bg-blue-600 hover:bg-blue-700 text-white"
                >
                  <Heart className="h-4 w-4 mr-1.5" />
                  Donate
                </Button>
              </Link>
            </div>
          </div>
        )}
      </header>

      <main className="flex-1">
        <Outlet />
      </main>

      <SiteFooter />
    </div>
  );
}